// Merge EB contact + property details -> WF10-normalized lead shape.
const contact = $('Split EB Leads').item.json;
const prop = $input.first().json || {};
const hasProp = !!(prop && prop.public_id);
const title = hasProp ? prop.title : ('Propiedad ' + (contact.property_id || 'EasyBroker'));
const price = hasProp && prop.operations && prop.operations[0] ? prop.operations[0].formatted_amount : 'Precio por confirmar';
const loc = hasProp && prop.location ? (typeof prop.location==='object' ? prop.location.name : prop.location) : '';
const op = hasProp && prop.operations && prop.operations[0] ? prop.operations[0].type : 'venta';
return [{ json: {
  phone: (contact.phone||'').replace(/[^\d]/g,''),
  email: contact.email || null,
  name: contact.name || null,
  message: contact.message || '',
  listing_id: contact.property_id || null,
  property_title: title,
  property_address: loc,
  property_price: price,
  listing_type: op,
  property_public_id: /^EB-/i.test(String(contact.property_id || '')) ? contact.property_id : null,
  source: 'easybroker',
  eb_contact_id: contact.contact_id || null
}}];

// Route decision per lead. The Postgres node ("Check Returning Lead + Time")
// runs once per normalized lead and (LEFT JOIN on time_ctx) returns exactly one
// row per input item, index-aligned with "Split & Normalize Leads". So iterate
// ALL items and pair by index -- the old code used $input.first() + a single
// returned item, so a batch of >1 lead only processed the FIRST and silently
// dropped the rest.
const dbRows = $input.all();
const leads = $('Split & Normalize Leads').all();
const out = [];

for (let i = 0; i < dbRows.length; i++) {
  const db = dbRows[i].json;
  const lead = (leads[i] || leads[0]).json;

  if (!lead.phone) {
    out.push({ json: { route: 'skip', reason: 'no_phone' } });
    continue;
  }

  const isReturning = !!db.existing_conv_id;
  const sameProperty = db.same_property === true;
  const isDay = db.is_day !== false; // Default to day if query returns no rows

  if (isReturning && sameProperty) {
    out.push({ json: {
      route: 'returning_same',
      existing_conv_id: db.existing_conv_id,
      assigned_agent_id: db.assigned_agent_id,
      existing_mode: db.existing_mode,
      ...lead,
    }});
  } else if (isDay) {
    out.push({ json: {
      route: 'day_auction',
      is_returning_diff: isReturning && !sameProperty,
      ...lead,
    }});
  } else {
    out.push({ json: {
      route: 'night_queue',
      is_returning_diff: isReturning && !sameProperty,
      ...lead,
    }});
  }
}

return out;

// Notify the assigned agent about a returning lead (same property).
const data = $('Route Decision').first().json;
const conv = $input.first().json;

if (!data.assigned_agent_id) {
  return [{ json: { skip: true, reason: 'no_assigned_agent' } }];
}

return [{
  json: {
    number: data.assigned_agent_id, // Will be resolved to phone below
    conversation_id: data.existing_conv_id,
    lead_name: data.name,
    lead_phone: data.phone,
    property_title: data.property_title,
    message: `Lead recurrente: ${data.name || data.phone} volvio a preguntar por ${data.property_title}. Ya lo tienes asignado.`
  }
}];

// Prepare data for WF3a auction call.
const lead = $('Route Decision').first().json;
const conv = $input.first().json;

// Build cache payload from scraper data
const cachePayload = {
  title: lead.property_title,
  price: lead.property_price,
  location: lead.property_address,
  operation_type: lead.listing_type,
  source: 'inmuebles24_scraper'
};

return [{
  json: {
    // For WF3a
    conversation_id: conv.conversation_id,
    lead_phone: conv.lead_phone,
    lead_name: conv.lead_name || lead.name,
    property_id: lead.listing_id || 'unknown',
    property_title: lead.property_title,
    property_price: lead.property_price,
    property_public_id: conv.property_public_id || lead.property_public_id || null,
    assigned_agent_id: null,
    // For caching
    cache_property_id: lead.listing_id || 'unknown',
    cache_payload: cachePayload
  }
}];

