// EB poll: filter new (id>cursor) & source!=Inmuebles24; advance cursor; emit a log row + lead rows.
const response = $input.first().json;
const content = Array.isArray(response.content) ? response.content : [];
const ok = Array.isArray(response.content);
const sd = $getWorkflowStaticData('global');
let lastId = sd.lastEbContactId;
if (lastId === undefined || lastId === null) lastId = 39328174; // baseline = current max, avoids dumping history
const newMax = content.length ? Math.max(lastId, ...content.map(c=>c.id)) : lastId;
const fresh = content.filter(c => c.id > lastId && c.source !== 'Inmuebles24');
sd.lastEbContactId = newMax;
const out = [{ json: {
  __log: true,
  run_id: 'eb-' + Date.now(),
  started_at: new Date().toISOString(),
  status: ok ? 'ok' : 'error',
  total_scraped: content.length,
  new_listings: fresh.length,
  error_message: ok ? null : 'No content in EB response'
}}];
for (const c of fresh.sort((a,b)=>a.id-b.id)) out.push({ json: {
  __log: false,
  eb_contact_id: c.id, contact_id: c.contact_id||null, name: c.name||null,
  phone: (c.phone||'').replace(/[^\d]/g,''), email: c.email||null,
  property_id: c.property_id||null, message: c.message||'', eb_source: c.source||'EasyBroker'
}});
return out;
